INSERT INTO feature VALUES('pr-closing-keywords','workflow','Closing keywords only on a body''s head lines',NULL,'implemented','ordinary',NULL,'`pr:open` refuses a closing keyword (close, fix or resolve, in any tense, before `#n` or `owner/name#n`) anywhere but the exact `Closes #n` lines at the head of a pull request body, quoted as code or not: GitHub closes the issue an unquoted one names on merge, and `pr:open` and the claim lifecycle take a quoted one as closed; the commit rules refuse one in a commit message anywhere but its own `Closes #n` line, and `issue:file` notes one in an issue body.',NULL,'.config/bodies/opening.json .config/commits/cases.json',NULL,NULL);
